export function calculateDimensionScore(responses: number[]): number {
  if (responses.length === 0) return 0;
  const sum = responses.reduce((a, b) => a + b, 0);
  const max = responses.length * 5;
  return Math.round((sum / max) * 100);
}

export function calculateGlobalScore(dimensions: DimensionScore[]): number {
  if (dimensions.length === 0) return 0;
  const sum = dimensions.reduce((acc, d) => acc + d.score, 0);
  return Math.round(sum / dimensions.length);
}

export function getMaturityLevel(score: number): MaturityLevel {
  if (score >= 80) return 'advanced';
  if (score >= 60) return 'intermediate';
  if (score >= 40) return 'emerging';
  return 'initial';
}
